      var juz = MAP.juz[p - 1], sName = 'سورة ' + C.arabicNames[first - 1], jName = 'الجزء ' + arNum(juz);
      // margin notes (hizb quarters, sajdas): on the outer edge — right for a right-hand page, left for a left-hand one
