      var ml = document.querySelector('.bk-mletters');
      if (ml) { ml.innerHTML = '<b>' + RS.fmt(o.letters, C.lang) + '</b><small>' + ({ ar: 'حرفًا', ur: 'حروف', en: 'letters', fr: 'lettres', es: 'letras', ru: 'букв' }[C.lang] || 'letters') + '</small>'; ml.hidden = false; }
