                         ios: ['اضغط «aA» أو أيقونة الإعدادات بجانب عنوان الموقع.', 'اختر «إعدادات الموقع» ← «الميكروفون» ← «سماح».', 'أو من إعدادات الآيفون: «Safari» ← «الميكروفون» ← «سماح».'],
